model User {
  id          Int          @id @default(autoincrement())
  username    String       @unique
  documents   Document[]   @relation("DocumentOwner")
  versions    Version[]
  permissions Permission[]
}

model Document {
  id          Int          @id @default(autoincrement())
  title       String
  content     String       @default("")
  ownerId     Int
