import { type WebSocketFn } from "wasp/server/webSocket";

let ioInstance: any = null;

export const webSocketFn: WebSocketFn = (io, context) => {
  ioInstance = io;

  io.on("connection", (socket) => {
    const user = socket.data.user;

    socket.on("join-document", (documentId: number) => {
      socket.join(`document-${documentId}`);
    });

    socket.on("leave-document", (documentId: number) => {
      socket.leave(`document-${documentId}`);
    });

    socket.on("edit-document", async ({ documentId, content }: { documentId: number; content: string }) => {
      if (!user) return;

      const doc = await context.entities.Document.findUnique({
        where: { id: documentId },
        include: { permissions: true },
      });

      if (!doc) return;

      const isOwner = doc.ownerId === user.id;
      const hasEditPermission = doc.permissions.some(
        (p) => p.userId === user.id && p.role === "EDIT"
      );

      if (isOwner || hasEditPermission) {
        await context.entities.Document.update({
          where: { id: documentId },
          data: { content },
        });

        socket.to(`document-${documentId}`).emit("document-updated", { content, senderId: user.id });
      }
    });

    socket.on("disconnect", () => {
      // Automatically cleaned up by socket.io
    });
  });
};

export const broadcastDocumentUpdate = (documentId: number, content: string, senderId?: number) => {
  if (ioInstance) {
    ioInstance.to(`document-${documentId}`).emit("document-updated", { content, senderId });
  }
};

import { HttpError } from "wasp/server";
import type { GetDocuments, GetDocument } from "wasp/server/operations";

export const getDocuments: GetDocuments<void, any[]> = async (_args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const userId = context.user.id;

  return context.entities.Document.findMany({
    where: {
      OR: [
        { ownerId: userId },
        {
          permissions: {
            some: { userId },
          },
        },
      ],
    },
    orderBy: { updatedAt: "desc" },
    include: {
      owner: {
        select: { id: true, username: true },
      },
    },
  });
};

export const getDocument: GetDocument<{ id: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const userId = context.user.id;
  const docId = args.id;

  const doc = await context.entities.Document.findUnique({
    where: { id: docId },
    include: {
      owner: {
        select: { id: true, username: true },
      },
      permissions: {
        include: {
          user: {
            select: { id: true, username: true },
          },
        },
      },
      versions: {
        orderBy: { createdAt: "desc" },
        include: {
          author: {
            select: { id: true, username: true },
          },
        },
      },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === userId;
  const permission = doc.permissions.find((p) => p.userId === userId);

  if (!isOwner && !permission) {
    throw new HttpError(403, "Access Denied");
  }

  const role = isOwner ? "OWNER" : permission ? permission.role : "NONE";

  return {
    ...doc,
    userRole: role,
  };
};

import { HttpError } from "wasp/server";
import type {
  CreateDocument,
  UpdateDocumentContent,
  SaveVersion,
  RestoreVersion,
  ShareDocument,
  RevokePermission,
} from "wasp/server/operations";
import { broadcastDocumentUpdate } from "./websocketSetup";

export const createDocument: CreateDocument<{ title: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  if (!args.title || args.title.trim() === "") {
    throw new HttpError(400, "Title is required");
  }

  return context.entities.Document.create({
    data: {
      title: args.title,
      ownerId: context.user.id,
      content: "",
    },
  });
};

export const updateDocumentContent: UpdateDocumentContent<{ id: number; content: string }, any> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const updatedDoc = await context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });

  // Broadcast update to others
  broadcastDocumentUpdate(args.id, args.content, context.user.id);

  return updatedDoc;
};

export const saveVersion: SaveVersion<{ id: number; content: string }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied");
  }

  // Create new version
  const version = await context.entities.Version.create({
    data: {
      documentId: args.id,
      content: args.content,
      authorId: context.user.id,
    },
  });

  // Update document's primary content and updatedAt
  await context.entities.Document.update({
    where: { id: args.id },
    data: { content: args.content },
  });

  // Broadcast update to all clients
  broadcastDocumentUpdate(args.id, args.content);

  return version;
};

export const restoreVersion: RestoreVersion<{ id: number; versionId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
    include: { permissions: true },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  const hasEditPermission = doc.permissions.some(
    (p) => p.userId === context.user.id && p.role === "EDIT"
  );

  if (!isOwner && !hasEditPermission) {
    throw new HttpError(403, "Access Denied");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: args.versionId },
  });

  if (!version || version.documentId !== args.id) {
    throw new HttpError(404, "Version not found");
  }

  // Update document content to that version's content
  await context.entities.Document.update({
    where: { id: args.id },
    data: { content: version.content },
  });

  // Broadcast the change to all other active WebSocket clients immediately
  broadcastDocumentUpdate(args.id, version.content);

  return { success: true };
};

export const shareDocument: ShareDocument<{ id: number; username: string; role: string }, any> = async (
  args,
  context
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  if (!isOwner) {
    throw new HttpError(403, "Only the owner can share the document");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: args.username },
  });

  if (!targetUser) {
    throw new HttpError(404, `User ${args.username} not found`);
  }

  if (targetUser.id === context.user.id) {
    throw new HttpError(400, "You cannot share the document with yourself");
  }

  if (args.role !== "VIEW" && args.role !== "EDIT") {
    throw new HttpError(400, "Role must be VIEW or EDIT");
  }

  // Upsert the permission
  return context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: targetUser.id,
      },
    },
    update: {
      role: args.role,
    },
    create: {
      documentId: args.id,
      userId: targetUser.id,
      role: args.role,
    },
  });
};

export const revokePermission: RevokePermission<{ id: number; userId: number }, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: args.id },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const isOwner = doc.ownerId === context.user.id;
  if (!isOwner) {
    throw new HttpError(403, "Only the owner can revoke permissions");
  }

  return context.entities.Permission.delete({
    where: {
      documentId_userId: {
        documentId: args.id,
        userId: args.userId,
      },
    },
  });
};

import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: (data: any) => {
    if (!data.username) {
      throw new Error("Username is required");
    }
    return data.username;
  },
});

